(()=>{const e=document.querySelector(".menu__btn"),t=document.querySelector(".navigation"),i=document.querySelectorAll(".navigation__item"),n=window.matchMedia("(min-width: 37.5em)");[...i].forEach(e=>{e.addEventListener("click",()=>{document.querySelector(".navigation__item--active")?.classList.remove("navigation__item--active"),e.classList.add("navigation__item--active")})}),e.addEventListener("click",function(){t.classList.toggle("navigation--active")}),n.addEventListener("change",function(e){e.matches&&t.classList.remove("navigation--active")})})();